using System.Runtime.InteropServices;

namespace IndustrialYolo.Onnx;

public sealed record NumericComparison(int Count, double MaximumAbsoluteError);

public static class NumericReference
{
    public const string InputSha256 = "5F598DA750EAE012350FC7B4B49B154C609104EE2B65A9AA3AC5D51C7C469863";
    // Generated by reference_yolox_nano.py, Python ORT1.27.0/NumPy2.5.0, CPU, opt disabled.
    private static readonly (int Index, float Value)[] Samples =
    [
        (0, 1.3127425909042358f), (1, .8245121836662292f), (2, .9872743487358093f),
        (3, .39399784803390503f), (4, 3.9637088775634766e-6f), (5, .13809305429458618f),
        (84, .0008854269981384277f), (85, 1.295704960823059f), (89, 5.990266799926758e-6f),
        (170, 1.3482954502105713f), (2719, .002502232789993286f), (5000, .004441946744918823f),
        (10000, .014893889427185059f), (30000, .004058569669723511f), (100000, .004638344049453735f),
        (200000, .0019035637378692627f), (250000, .00080147385597229f), (300000, .005226105451583862f),
        (301660, .00321003794670105f), (301664, .0021174848079681396f)
    ];

    public static bool Near(float actual, float expected) => float.IsFinite(actual) && float.IsFinite(expected) &&
        Math.Abs((double)actual - expected) <= 1e-5 + 1e-4 * Math.Abs((double)expected);

    public static void CheckSamples(YoloXRawOutput output)
    {
        foreach (var (index, expected) in Samples)
            if (!Near(output.Values[index], expected)) throw new InvalidOperationException($"Python sample mismatch at {index}.");
    }

    public static NumericComparison Compare(ReadOnlySpan<float> actual, ReadOnlySpan<float> expected)
    {
        if (actual.Length != expected.Length || actual.Length == 0) throw new ArgumentException("Reference lengths must agree and be positive.");
        double maximum = 0;
        for (int i = 0; i < actual.Length; i++)
        {
            if (!Near(actual[i], expected[i])) throw new InvalidOperationException($"Reference mismatch at {i}.");
            maximum = Math.Max(maximum, Math.Abs((double)actual[i] - expected[i]));
        }
        return new(actual.Length, maximum);
    }

    public static NumericComparison CompareFile(YoloXRawOutput actual, string path)
    {
        if (!BitConverter.IsLittleEndian) throw new PlatformNotSupportedException("Reference is little-endian float32.");
        using FileStream file = new(path, FileMode.Open, FileAccess.Read, FileShare.Read);
        if (file.Length != YoloXNanoSession.OutputCount * sizeof(float)) throw new ArgumentException("Raw reference must be301665 little-endian float32 values.");
        byte[] bytes = new byte[YoloXNanoSession.OutputCount * sizeof(float)];
        file.ReadExactly(bytes);
        return Compare(actual.Values, MemoryMarshal.Cast<byte, float>(bytes));
    }
}
